from __future__ import annotations
import subprocess, textwrap, unittest
from pathlib import Path
WEB=Path(__file__).resolve().parents[1]

class PC15IntelligenceRefinementParityTest(unittest.TestCase):
    def run_node(self, source:str)->None:
        result=subprocess.run(['node','--input-type=module','-e',source],cwd=WEB,text=True,capture_output=True,check=False)
        self.assertEqual(result.returncode,0,result.stderr or result.stdout)

    def test_weekly_coach_is_evidence_backed_prioritized_and_bounded(self):
        self.run_node(textwrap.dedent(r'''
            import assert from 'node:assert/strict';
            import {createStudyStore} from './runtime/state.js';
            import {deriveWeeklyCoach} from './runtime/intelligence.js';
            let now='2026-09-07T10:00:00-03:00'; const repo={load(){return {status:'empty',state:null}},save(){return {status:'saved'}},clear(){}}; const store=createStudyStore({repository:repo,now:()=>now});
            store.createPlan({name:'Coach',mode:'EXAM_PLAN'},{activate:true}); const s=store.addSubject({name:'Law'}),t=store.addTopic({subjectId:s.id,name:'Rights'}),q=store.addQuestion({subjectId:s.id,topicId:t.id,prompt:'Q',answer:'A'});
            for(let i=0;i<5;i++)store.answerQuestion(q.id,i<2?'A':'B');
            let st=store.getState(); const review=st.reviews.find(r=>r.planId===st.activePlanId); assert.ok(review); store.replaceState({...st,reviews:st.reviews.map(r=>r.id===review.id?{...r,dueAt:'2026-09-06T09:00:00-03:00'}:r)});
            const a=store.addActivity({title:'Monday focus',kind:'study',activityType:'THEORY',durationMinutes:30,scheduledFor:'2026-09-07'}); store.startFocus({activityId:a.id,durationMinutes:30}); now='2026-09-07T10:30:00-03:00'; store.completeFocus();
            const c=deriveWeeklyCoach(store.getState(),new Date(now)); assert.ok(c.items.length>0&&c.items.length<=5); assert.ok(c.studiedMinutes>=30); assert.ok(c.evidenceCount>0); assert.ok(c.items.some(x=>x.signalKind==='review-backlog')); assert.ok(c.items.some(x=>x.signalKind==='practice-accuracy'));
            const order={'readiness-risk':0,'readiness-stable':0,'reschedule-ready':1,'review-backlog':2,'practice-accuracy':3,'schedule-drift':4,'mock-exam-signal':5,'consistency-win':6,'evidence-empty':7}; for(let i=1;i<c.items.length;i++)assert.ok((order[c.items[i-1].signalKind]??99)<=(order[c.items[i].signalKind]??99));
        '''))

    def test_smart_cleanup_covers_original_issue_classes_and_is_review_only(self):
        self.run_node(textwrap.dedent(r'''
            import assert from 'node:assert/strict'; import {createStudyStore} from './runtime/state.js'; import {buildContentCleanupPreview} from './runtime/intelligence.js';
            const now='2026-09-07T12:00:00Z',repo={load(){return {status:'empty',state:null}},save(){return {status:'saved'}},clear(){}}; const store=createStudyStore({repository:repo,now:()=>now}); store.createPlan({name:'Cleanup',mode:'GENERAL_SKILL'},{activate:true}); const s=store.addSubject({name:'S'}),orphan=store.addTopic({subjectId:s.id,name:'Unused'}); store.addQuestion({prompt:'Duplicate?',answer:'A'}); store.addQuestion({prompt:' duplicate? ',answer:'A'}); const m1=store.addMaterial({title:'Old',kind:'link',locator:'local',tags:['Exam']}),m2=store.addMaterial({title:'Tagged',kind:'note',tags:[' exam ']}); let st=store.getState(); const raw={...st,materials:st.materials.map(m=>m.id===m1.id?{...m,archived:true,tags:['Exam'],updatedAt:'2026-05-01T00:00:00Z'}:m.id===m2.id?{...m,tags:[' exam ']}:m)}; const rawBefore=JSON.stringify(raw); const p=buildContentCleanupPreview(raw,new Date(now));
            assert.equal(JSON.stringify(raw),rawBefore); assert.equal(p.summary['duplicate-question'],1); assert.equal(p.summary['orphan-topic'],1); assert.equal(p.summary['stale-resource'],1); assert.equal(p.summary['inconsistent-tag'],2); assert.equal(p.healthScorePercent,87); assert.equal(p.applicableCount,0); assert.ok(p.previewActions.length>=4); assert.ok(p.previewActions.every(x=>x.destructive===false&&x.requiresConfirmation===true)); const currentBefore=JSON.stringify(store.getState()); const currentPreview=buildContentCleanupPreview(store.getState(),new Date(now)); assert.throws(()=>store.applyContentCleanupPreview(currentPreview),/review-only/); assert.equal(JSON.stringify(store.getState()),currentBefore); assert.notEqual(store.getState().topics.find(x=>x.id===orphan.id).status,'archived');
        '''))

    def test_exam_report_is_structured_source_backed_and_pdf_excludes_freeform_notes(self):
        self.run_node(textwrap.dedent(r'''
            import assert from 'node:assert/strict'; import {createStudyStore} from './runtime/state.js'; import {buildExamReportSnapshot,renderExamReportHtml,renderExamReportPdf} from './runtime/intelligence.js';
            let now='2026-09-07T10:00:00Z',repo={load(){return {status:'empty',state:null}},save(){return {status:'saved'}},clear(){}}; const store=createStudyStore({repository:repo,now:()=>now}); store.createPlan({name:'<Exam & Report>',mode:'EXAM_PLAN'},{activate:true}); const a=store.addActivity({title:'Study',kind:'study',activityType:'THEORY',durationMinutes:25,scheduledFor:'2026-09-07'}); store.startFocus({activityId:a.id,durationMinutes:25,note:'SECRET_FREEFORM_NOTE'}); now='2026-09-07T10:25:00Z'; store.completeFocus({note:'SECRET_FREEFORM_NOTE'}); const r=buildExamReportSnapshot(store.getState(),new Date(now)); assert.equal(r.freeformNotesIncluded,false); assert.ok(r.metricProvenance.some(x=>x.source==='raw-evidence')); assert.ok(r.metricProvenance.some(x=>x.source==='content-health')); assert.ok(Array.isArray(r.nextActions)&&r.nextActions.length>0); const html=renderExamReportHtml(r); assert.ok(html.includes('&lt;Exam &amp; Report&gt;')); assert.ok(!html.includes('SECRET_FREEFORM_NOTE')); const pdf=renderExamReportPdf(r); const text=new TextDecoder().decode(pdf); assert.ok(text.startsWith('%PDF-1.4')); assert.ok(!text.includes('SECRET_FREEFORM_NOTE')); assert.ok(text.includes('Metric provenance'));
        '''))

    def test_exam_runbook_preserves_no_date_truth_and_original_priority_order(self):
        self.run_node(textwrap.dedent(r'''
            import assert from 'node:assert/strict'; import {createStudyStore} from './runtime/state.js'; import {buildExamRunbook} from './runtime/intelligence.js';
            const now='2026-09-07T12:00:00-03:00',repo={load(){return {status:'empty',state:null}},save(){return {status:'saved'}},clear(){}}; const store=createStudyStore({repository:repo,now:()=>now}); store.createPlan({name:'Runbook',mode:'EXAM_PLAN'},{activate:true}); let r=buildExamRunbook(store.getState(),new Date(now)); assert.equal(r.status,'no-date'); assert.deepEqual(r.items,[]);
            store.updatePublicExamTarget({organization:'Agency',role:'Role',board:'Board',dateStatus:'confirmed',examDate:'2026-09-09'}); const s=store.addSubject({name:'Law'}),t=store.addTopic({subjectId:s.id,name:'Weak'}),q=store.addQuestion({subjectId:s.id,topicId:t.id,prompt:'Q',answer:'A'}); store.answerQuestion(q.id,'B'); let st=store.getState(); assert.ok(st.reviews.length); store.replaceState({...st,reviews:st.reviews.map(x=>({...x,dueAt:'2026-09-06T12:00:00-03:00'}))}); store.addActivity({title:'Missed',kind:'study',activityType:'THEORY',durationMinutes:30,scheduledFor:'2026-09-06'}); r=buildExamRunbook(store.getState(),new Date(now)); assert.equal(r.status,'ready'); assert.equal(r.daysRemaining,2); assert.ok(r.items.length<=6); assert.deepEqual(r.items.slice(0,3).map(x=>x.action),['recover-reviews','final-review','protect-schedule']); assert.ok(r.items.some(x=>x.action==='attack-weak-area')); assert.ok(r.items.every(x=>x.navigation));
        '''))

    def test_seven_day_sprint_only_mutates_existing_unlocked_candidates(self):
        self.run_node(textwrap.dedent(r'''
            import assert from 'node:assert/strict'; import {createStudyStore} from './runtime/state.js'; import {buildStudySprintPreview} from './runtime/intelligence.js';
            const now='2026-09-07T12:00:00-03:00',repo={load(){return {status:'empty',state:null}},save(){return {status:'saved'}},clear(){}}; const store=createStudyStore({repository:repo,now:()=>now}); store.createPlan({name:'Sprint',mode:'EXAM_PLAN'},{activate:true}); store.updatePublicExamTarget({organization:'A',role:'R',board:'B',dateStatus:'confirmed',examDate:'2026-09-12'}); const ids=[]; for(let i=0;i<8;i++){const day=String(7+(i%7)).padStart(2,'0'); const a=store.addActivity({title:`A${i}`,kind:'study',activityType:'THEORY',durationMinutes:90,scheduledFor:`2026-09-${day}`,scheduledStartMinute:600+i*10}); ids.push(a.id);} const locked=store.addActivity({title:'Locked',kind:'study',activityType:'THEORY',durationMinutes:90,scheduledFor:'2026-09-08',scheduledStartMinute:900,locked:true}); const outside=store.addActivity({title:'Outside',kind:'study',activityType:'THEORY',durationMinutes:90,scheduledFor:'2026-09-20'}); const before=structuredClone(store.getState()); const p=buildStudySprintPreview(store.getState(),new Date(now)); assert.equal(p.horizonDays,7); assert.equal(p.candidateCount,7); assert.equal(p.candidateIds.length,7); assert.ok(!p.candidateIds.includes(locked.id)); assert.ok(!p.candidateIds.includes(outside.id)); assert.ok(p.candidateIds.every(id=>before.activities.some(a=>a.id===id))); assert.ok(p.mutations.every(m=>p.candidateIds.includes(m.activityId)&&m.proposedDurationMinutes<=m.currentDurationMinutes)); store.applyStudySprintPreview(p); const after=store.getState(); assert.equal(after.activities.length,before.activities.length); assert.deepEqual(after.activities.map(a=>a.id).sort(),before.activities.map(a=>a.id).sort()); for(const id of p.candidateIds){const b=before.activities.find(a=>a.id===id),a=after.activities.find(x=>x.id===id); assert.equal(a.scheduledFor,b.scheduledFor); assert.equal(a.scheduledStartMinute,b.scheduledStartMinute); assert.equal(a.status,b.status); assert.equal(a.locked,b.locked); assert.ok(a.durationMinutes<=b.durationMinutes);} assert.deepEqual(after.activities.find(a=>a.id===locked.id),before.activities.find(a=>a.id===locked.id)); const stale=buildStudySprintPreview(after,new Date(now)); store.addMaterial({title:'Revision bump',kind:'note'}); assert.throws(()=>store.applyStudySprintPreview(stale),/stale/);
        '''))

    def test_four_onboarding_blueprints_are_preview_first_and_provision_atomically(self):
        self.run_node(textwrap.dedent(r'''
            import assert from 'node:assert/strict'; import {createStudyStore} from './runtime/state.js'; import {SAMPLE_PLAN_BLUEPRINTS,listSamplePlanBlueprints} from './runtime/refinement.js';
            assert.deepEqual(Object.keys(SAMPLE_PLAN_BLUEPRINTS).sort(),['certification-bootcamp','free-study-habit','public-exam-12-week','university-semester']); assert.equal(listSamplePlanBlueprints().length,4); assert.deepEqual(SAMPLE_PLAN_BLUEPRINTS['public-exam-12-week'].scheduleRules.map(x=>[x.weekday,x.startMinute,x.durationMinutes]),[[1,1140,90],[3,1140,90],[5,1140,75],[6,540,120]]); assert.equal(SAMPLE_PLAN_BLUEPRINTS['public-exam-12-week'].weeklyGoalHours,20); assert.equal(SAMPLE_PLAN_BLUEPRINTS['university-semester'].weeklyGoalHours,12); assert.equal(SAMPLE_PLAN_BLUEPRINTS['certification-bootcamp'].preferredSessionMinutes,40); assert.equal(SAMPLE_PLAN_BLUEPRINTS['free-study-habit'].adaptivePlanningEnabled,false);
            let saves=0; const repo={load(){return {status:'empty',state:null}},save(){saves++;return {status:'saved'}},clear(){}}; const store=createStudyStore({repository:repo,now:()=> '2026-09-07T12:00:00-03:00'}); const beforeSaves=saves,beforeRevision=store.getState().revision; assert.equal(store.getState().plans.some(p=>p.name==='University semester'),false); const plan=store.provisionSamplePlan('university-semester',{locale:'en',planName:'University semester',activate:true}); assert.equal(saves,beforeSaves+1); const st=store.getState(); assert.equal(st.revision,beforeRevision+1); assert.equal(st.activePlanId,plan.id); assert.equal(st.subjects.filter(x=>x.planId===plan.id).length,3); assert.equal(st.topics.filter(x=>x.planId===plan.id).length,6); assert.equal(st.activities.filter(x=>x.planId===plan.id&&x.origin==='seed').length,3); assert.deepEqual(st.activities.filter(x=>x.planId===plan.id).map(x=>x.durationMinutes),[75,90,120]); assert.equal(st.goals.find(x=>x.planId===plan.id&&x.metric==='study-hours').target,12);
        '''))

    def test_ui_offline_and_source_surface_pc15_contract(self):
        ui=(WEB/'src/react/App.tsx').read_text(); sw=(WEB/'service-worker.js').read_text(); source=(WEB/'src/refinement.ts').read_text()
        for token in ('12-week public exam','University semester','Certification bootcamp','Free-study habit','Weekly schedule preview','Preview smart cleanup','Preview 7-day sprint','Export PDF exam report','Preview only. Cleanup actions are non-destructive','cannot create IDs, move starts, change status, touch locked activities, or increase duration'):
            self.assertIn(token,ui)
        for token in ('review-backlog','mock-exam-signal','stale-resource','stale-plan','inconsistent-tag','stale-review','broken-schedule-alignment','freeformNotesIncluded:false','horizonDays:7'):
            self.assertIn(token,source)
        self.assertIn('runtime/refinement.js',sw)

if __name__=='__main__': unittest.main()
